; Title menu: goes to start_demo when title_timeout runs out; handles F7 or port-1 fire (start), F3 (players), F5 (opponent) and the L/R handedness keys. Returns when a game is to start.
title_menu_loop
        lda attract_countdown
        ora title_timeout_hi
        bne title_scan_keys
        jmp start_demo
title_scan_keys
        lda #$00
        sta key_scan_mode
        jsr keyboard_scan
        lda key_pending
        beq title_idle
        lda #$00
        sta key_pending
        lda key_code
        jmp title_handedness_keys
title_function_keys
        and #$7f
        cmp #$03
        beq title_start_pressed
        cmp #$06
        beq title_toggle_opponent
        cmp #$05
        beq title_toggle_players
title_idle
        lda title_timeout_hi            ; message $0E at the handedness message position once title_timeout is below $0802
        cmp #$08
        bne title_check_fire
        lda attract_countdown
        cmp #$02
        bcs title_check_fire
        lda #$0e
        ldx #$0a
        ldy #$02
        jsr print_message
title_check_fire
        lda CIAPRB
        and #$10
        bne title_menu_loop
title_start_pressed
        jsr wait_fire_release
l_0900 = * + 1
        lda #$10
        sta frame_countdown
l_0903
        lda frame_countdown
        bne l_0903
        rts
; F5: toggles human_opponent_mode and its highlight, waits for fire release and restarts the timeout.
title_toggle_opponent
        lda human_opponent_mode
        eor #$01
        sta human_opponent_mode
        sta saved_human_opponent_mode
        jsr toggle_opponent_highlight
title_option_done
        jsr wait_fire_release
        lda #$09
        sta title_timeout_hi
        lda #$60
        sta attract_countdown
        lda #$04
        sta frame_countdown
title_wait_frames
        lda frame_countdown
        bne title_wait_frames
        jmp title_menu_loop
; F3: toggles two_player_mode and its highlight.
title_toggle_players
        lda two_player_mode
        eor #$01
        sta two_player_mode
        sta saved_two_player_mode
        jsr toggle_players_highlight
        jsr wait_fire_release
        lda #$09
        sta title_timeout_hi
        lda #$60
        sta attract_countdown
        lda #$04
        sta frame_countdown
        bne title_wait_frames
; Waits until the fire buttons of both joystick ports are released.
wait_fire_release
        lda CIAPRA
        and CIAPRB
        and #$10
        beq wait_fire_release
        rts
; Key code in A: L/Shift-L set joystick 1/2 to left-handed, R/Shift-R to right-handed, each with its message; other keys go to title_function_keys.
title_handedness_keys
        cmp #$2a
        beq set_joy1_left
        cmp #$aa
        beq set_joy2_left
        cmp #$11
        beq set_joy1_right
        cmp #$91
        beq set_joy2_right
        jmp title_function_keys
set_joy1_left
        lda #$08
        ldx #$0a
        ldy #$02
        jsr print_message
        lda #$00
        sta joy_handedness_p1
        beq l_09a6
set_joy2_left
        lda #$0a
        tax
        ldy #$02
        jsr print_message
        lda #$00
        sta joy_handedness_p2
        beq l_09a6
set_joy1_right
        lda #$09
        ldx #$0a
        ldy #$02
        jsr print_message
        lda #$01
        sta joy_handedness_p1
        bne l_09a6
set_joy2_right
        lda #$0d
        ldx #$0a
        ldy #$02
        jsr print_message
        lda #$01
        sta joy_handedness_p2
l_09a6
        jmp title_option_done
; Fills colour RAM $D800-$DBFF with A.
fill_colour_ram
        ldx #$00
l_09ab
        sta ld800,x
        sta ld900,x
        sta lda00,x
        sta ldb00,x
        inx
        bne l_09ab
